/**
 * Outlined Material Icons pulled from Google Fonts (https://fonts.google.com/icons).
 * Used via [rememberVectorPainter] across snippets and WASM preview to avoid runtime XML loading
 * and external icon library dependencies.
 */
object AppIcons {
    private fun createIcon(name: String, pathData: String): ImageVector {
        return ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f
        ).addPath(
            pathData = PathParser().parsePathString(pathData).toNodes(),
            fill = SolidColor(Color.Black)
        ).build()
    }

